// The formatting rules of blitz-format.
#pragma once
#include <string>
#include <vector>

namespace blitz::format {
	enum class keyword_style { preserve, lower, upper, capitalized };
	enum class spacing { preserve, spaced, compact };
	enum class paren_spacing { preserve, never };
	enum class ending_style { automatic, lf, crlf, cr };

	struct options {
		bool          indent_with_tabs      = true; // indent_style = tab | space
		int           indent_width          = 4;    // Spaces per level, when indenting with spaces
		bool          indent_case           = true; // Case and Default one level in from Select
		bool          indent_labels         = false; // .label at the indent of the code around it, instead of in column 1
		keyword_style keyword_case          = keyword_style::capitalized;
		spacing       operator_spacing      = spacing::spaced;
		spacing       separator_spacing     = spacing::spaced;  // The : between statements
		bool          comma_space           = true;
		bool          paren_inner_space     = false;
		paren_spacing paren_space           = paren_spacing::preserve; // Name (x) or Name(x)
		int           comment_gap           = 1;     // Spaces between code and a comment behind it, 0 keeps what is there
		bool          comment_space         = false; // ;text becomes ; text
		int           max_blank_lines       = 1;     // -1 for no limit
		int           blank_lines_around_declarations = 1; // Before a Function or Type (and its comments), and after it
		bool          align_assignments     = false; // Line up the = of assignments on consecutive lines
		bool          align_declares        = false; // Line up the names and = of Const, Dim, Local and Global on consecutive lines
		bool          trim_trailing_space   = true;
		bool          final_newline         = true;
		ending_style line_ending           = ending_style::automatic;
	};

	struct option_info {
		const char* name;
		const char* values;       // What can be written, such as "true | false"
		const char* default_text; // The default, written the same way
		const char* description;
	};

	/** Every option, in the order the documentation lists them.
	 */
	std::vector<option_info> const& option_list();

	/** Set an option by name (not case sensitive, - is the same as _). Returns false and an explanation in 'error' if the
	 * name or the value is not known.
	 */
	bool set_option(options& into, std::string key, std::string const& value, std::string& error);

	/** The options as `key = value` lines, which is the format of the .blitz-format file.
	 */
	std::string to_config(options const& from);
} // namespace blitz::format
